import { useEffect, useRef, useState } from 'react'
import { api, type AgentConfig, type Catalog, type HttpTool } from './api'
import { Badge, Field, Icon, Section, Toggle } from './ui'

// Fixed phrases the agent speaks as written (not generated by the LLM), so they must be
// in the agent's language.
const PHRASES = ['greeting', 'goodbye_message', 'nudge_message', 'repeat_message'] as const

// True when the text has letters but none from an Indic script, i.e. it is still English.
function looksEnglish(text: string) {
  return /[A-Za-z]/.test(text) && !/[ऀ-෿]/.test(text)
}

// Voices offered in every language, not just their own, so we can hear how they handle
// other languages. Sarvam doesn't guarantee a voice outside its own language; listen before using it.
const CROSS_LANGUAGE_VOICES = ['aparna_en_edtech']

function voiceFits(v: Catalog['voices'][number], language: string) {
  return (
    v.language === language ||
    (v.group === 'Hindi-English Code-Mixed' && ['en-IN', 'hi-IN'].includes(language)) ||
    CROSS_LANGUAGE_VOICES.includes(v.id)
  )
}

type Props = {
  catalog: Catalog
  value: AgentConfig
  onChange: (config: AgentConfig) => void
}

const EMPTY_TOOL: HttpTool = {
  name: '',
  description: '',
  method: 'POST',
  url: 'https://',
  headers: {},
  parameters: {},
  required: [],
  timeout_secs: 8,
}

export function AgentConfigForm({ catalog, value, onChange }: Props) {
  const set = <K extends keyof AgentConfig>(key: K, v: AgentConfig[K]) => onChange({ ...value, [key]: v })
  const latest = useRef(value)
  useEffect(() => {
    latest.current = value
  }, [value])
  const [translating, setTranslating] = useState('')

  const translatePhrases = async (language: string) => {
    const name = catalog.languages[language]
    setTranslating(`Translating greeting and messages to ${name}…`)
    try {
      const texts = Object.fromEntries(PHRASES.map((k) => [k, latest.current[k]]))
      const res = await api.translate(language, texts)
      onChange({ ...latest.current, ...res.texts })
      setTranslating(`Translated to ${name}. Review the greeting and messages, then save.`)
    } catch (e) {
      setTranslating(`Translation failed: ${e instanceof Error ? e.message : e}`)
    }
  }
  const englishPhrases = value.language !== 'en-IN' && PHRASES.some((k) => looksEnglish(value[k]))

  // The language's own voices first, then the cross-language ones.
  const voices = catalog.voices
    .filter((v) => voiceFits(v, value.language))
    .sort((a, b) => Number(a.language !== value.language && CROSS_LANGUAGE_VOICES.includes(a.id)) -
      Number(b.language !== value.language && CROSS_LANGUAGE_VOICES.includes(b.id)))

  const changeLanguage = (language: string) => {
    const stillValid = catalog.voices.some((v) => v.id === value.voice && voiceFits(v, language))
    // A language with no voices of its own (Malayalam) falls back to a cross-language voice.
    const firstVoice =
      catalog.voices.find((v) => v.language === language)?.id ??
      catalog.voices.find((v) => voiceFits(v, language))?.id ??
      value.voice
    const next = { ...value, language, voice: stillValid ? value.voice : firstVoice }
    onChange(next)
    latest.current = next
    if (language !== 'en-IN' && PHRASES.some((k) => looksEnglish(next[k]))) void translatePhrases(language)
  }

  const languageName = catalog.languages[value.language]

  return (
    <>
      <Section icon="chat" title="Conversation" description="What the agent says first and how it should behave.">
        <Field label="Greeting" hint="Spoken immediately when the call connects, exactly as written." wide>
          <input value={value.greeting} onChange={(e) => set('greeting', e.target.value)} />
        </Field>
        {(englishPhrases || translating) && (
          <div className={`inline-alert${!englishPhrases ? ' info' : ''}`}>
            <Icon name="globe" />
            <span className="grow">
              {englishPhrases
                ? `The greeting or messages are in English, so the agent will say them in English.`
                : translating}
            </span>
            {englishPhrases && (
              <button type="button" className="btn btn-secondary btn-sm" onClick={() => translatePhrases(value.language)}>
                Translate to {languageName}
              </button>
            )}
            {englishPhrases && translating && <span className="small">{translating}</span>}
          </div>
        )}
        <Field
          label="Prompt / instructions"
          hint="Persona, objective, context, guardrails and steps. Can be written in English for any language."
          wide
        >
          <textarea rows={9} value={value.instructions} onChange={(e) => set('instructions', e.target.value)} />
        </Field>
      </Section>

      <Section icon="globe" title="Language & voice" description="The agent replies in this language and speaks with this voice.">
        <Field label="Language">
          <select value={value.language} onChange={(e) => changeLanguage(e.target.value)}>
            {Object.entries(catalog.languages).map(([code, name]) => (
              <option key={code} value={code}>
                {name} ({code})
              </option>
            ))}
          </select>
        </Field>
        <Field label="Voice" hint={`${voices.length} Bulbul v4 Flash voices for ${languageName}`}>
          <select value={value.voice} onChange={(e) => set('voice', e.target.value)}>
            {voices.map((v) => (
              <option key={v.id} value={v.id}>
                {v.name} · {v.style}
                {v.group === 'Hindi-English Code-Mixed' ? ' (Hinglish)' : ''}
                {v.language !== value.language && CROSS_LANGUAGE_VOICES.includes(v.id) ? ' (English voice, test)' : ''}
              </option>
            ))}
          </select>
        </Field>
        <Field
          label={
            <>
              Speaking pace <span className="value">{value.pace.toFixed(2)}×</span>
            </>
          }
        >
          <input type="range" min={0.5} max={2} step={0.05} value={value.pace} onChange={(e) => set('pace', Number(e.target.value))} />
        </Field>
        <div className="field">
          <Toggle
            checked={value.auto_detect_language}
            onChange={(v) => set('auto_detect_language', v)}
            label="Follow the caller's language"
            hint={`Reply in whatever language the caller speaks instead of always ${languageName}.`}
          />
        </div>
      </Section>

      <Section
        icon="zap"
        title="Response speed & recognition"
        description="How quickly the agent decides you've finished speaking, and words it should hear correctly."
      >
        <div className="choice-cards wide">
          <button
            type="button"
            className={`choice${value.turn_detection === 'fast' ? ' active' : ''}`}
            onClick={() => set('turn_detection', 'fast')}
          >
            <Icon name="zap" />
            <div>
              <strong>Fast</strong>
              <span>Our server detects the pause · replies in ~1.2–1.4 s</span>
            </div>
          </button>
          <button
            type="button"
            className={`choice${value.turn_detection === 'sarvam' ? ' active' : ''}`}
            onClick={() => set('turn_detection', 'sarvam')}
          >
            <Icon name="wave" />
            <div>
              <strong>Sarvam VAD</strong>
              <span>Sarvam detects the pause · best on noisy lines · ~2.3 s</span>
            </div>
          </button>
        </div>
        <Field label="Pause that ends the caller's turn" hint="Shorter is faster, but may cut off people who pause mid-sentence.">
          <select
            value={value.end_of_speech_ms ?? ''}
            onChange={(e) => set('end_of_speech_ms', e.target.value ? Number(e.target.value) : null)}
          >
            <option value="">{value.turn_detection === 'fast' ? 'Default (300 ms)' : "Default (Sarvam's)"}</option>
            {[200, 250, 300, 400, 500, 700, 1000].map((ms) => (
              <option key={ms} value={ms}>
                {ms} ms
              </option>
            ))}
          </select>
        </Field>
        <Field label="Important words" hint="Names, brands and products the speech recognizer should favour. Comma separated.">
          <input
            value={value.important_words.join(', ')}
            placeholder="Acme, Riya, EMI"
            onChange={(e) =>
              set(
                'important_words',
                e.target.value.split(',').map((w) => w.trimStart()).filter((w, i, all) => w || i === all.length - 1),
              )
            }
          />
        </Field>
      </Section>

      <Section icon="settings" title="Call behaviour" description="Limits, hang-up and the fixed phrases the agent uses.">
        <Field
          label={
            <>
              Creativity <span className="value">{value.temperature.toFixed(2)}</span>
            </>
          }
          hint="Lower keeps answers consistent and on-script."
        >
          <input
            type="range"
            min={0}
            max={1}
            step={0.05}
            value={value.temperature}
            onChange={(e) => set('temperature', Number(e.target.value))}
          />
        </Field>
        <div className="field">
          <Toggle
            checked={value.end_call_enabled}
            onChange={(v) => set('end_call_enabled', v)}
            label="Agent can hang up"
            hint="Ends the call itself when the conversation is done."
          />
        </div>
        <Field label="Max call length (seconds)">
          <input
            type="number"
            min={30}
            max={1800}
            value={value.max_call_seconds}
            onChange={(e) => set('max_call_seconds', Number(e.target.value))}
          />
        </Field>
        <Field label="Silence before nudge (seconds)">
          <input
            type="number"
            min={4}
            max={60}
            value={value.idle_timeout_secs}
            onChange={(e) => set('idle_timeout_secs', Number(e.target.value))}
          />
        </Field>
        <Field label="Goodbye message" wide>
          <input value={value.goodbye_message} onChange={(e) => set('goodbye_message', e.target.value)} />
        </Field>
        <Field label="Nudge when the caller is silent">
          <input value={value.nudge_message} onChange={(e) => set('nudge_message', e.target.value)} />
        </Field>
        <Field label="Asking to repeat (if a reply fails)">
          <input value={value.repeat_message} onChange={(e) => set('repeat_message', e.target.value)} />
        </Field>
      </Section>

      <Section
        icon="wrench"
        title="Tools"
        description="Your HTTP APIs the agent can call during a conversation."
        aside={
          <button type="button" className="btn btn-secondary btn-sm" onClick={() => set('tools', [...value.tools, { ...EMPTY_TOOL }])}>
            <Icon name="plus" size={14} /> Add tool
          </button>
        }
      >
        {value.tools.length === 0 && (
          <div className="empty">
            No custom tools yet. Try the demo endpoint <code>http://localhost:7860/api/demo/order-status</code>.
          </div>
        )}
        {value.tools.map((tool, i) => (
          <ToolEditor
            key={i}
            tool={tool}
            onChange={(t) => set('tools', value.tools.map((x, j) => (j === i ? t : x)))}
            onRemove={() => set('tools', value.tools.filter((_, j) => j !== i))}
          />
        ))}
      </Section>
    </>
  )
}

function ToolEditor({
  tool,
  onChange,
  onRemove,
}: {
  tool: HttpTool
  onChange: (t: HttpTool) => void
  onRemove: () => void
}) {
  const [paramsText, setParamsText] = useState(JSON.stringify(tool.parameters, null, 2))
  const [headersText, setHeadersText] = useState(JSON.stringify(tool.headers, null, 2))
  const [jsonError, setJsonError] = useState('')

  const parseJson = (text: string, apply: (v: Record<string, never>) => void) => {
    try {
      apply(text.trim() ? JSON.parse(text) : {})
      setJsonError('')
    } catch {
      setJsonError('Invalid JSON')
    }
  }

  return (
    <div className="tool">
      <div className="tool-head">
        <Icon name="wrench" />
        <code className="grow">{tool.name || 'new_tool'}</code>
        <Badge tone="blue">{tool.method}</Badge>
        {jsonError && <Badge tone="red">{jsonError}</Badge>}
        <button type="button" className="btn btn-ghost btn-icon" onClick={onRemove} title="Remove tool">
          <Icon name="trash" />
        </button>
      </div>
      <Field label="Name" hint="snake_case, e.g. check_order_status">
        <input value={tool.name} onChange={(e) => onChange({ ...tool, name: e.target.value })} placeholder="check_order_status" />
      </Field>
      <Field label="Method">
        <select value={tool.method} onChange={(e) => onChange({ ...tool, method: e.target.value as 'GET' | 'POST' })}>
          <option>POST</option>
          <option>GET</option>
        </select>
      </Field>
      <Field label="When should the agent use it?" wide>
        <input value={tool.description} onChange={(e) => onChange({ ...tool, description: e.target.value })} />
      </Field>
      <Field label="URL" wide>
        <input value={tool.url} onChange={(e) => onChange({ ...tool, url: e.target.value })} />
      </Field>
      <Field label="Parameters" hint="JSON Schema properties">
        <textarea
          className="mono"
          rows={4}
          value={paramsText}
          placeholder='{"order_id": {"type": "string"}}'
          onChange={(e) => {
            setParamsText(e.target.value)
            parseJson(e.target.value, (v) => onChange({ ...tool, parameters: v }))
          }}
        />
      </Field>
      <Field label="Headers" hint="JSON, e.g. an Authorization header">
        <textarea
          className="mono"
          rows={4}
          value={headersText}
          placeholder='{"Authorization": "Bearer ..."}'
          onChange={(e) => {
            setHeadersText(e.target.value)
            parseJson(e.target.value, (v) => onChange({ ...tool, headers: v }))
          }}
        />
      </Field>
      <Field label="Required parameters" hint="Comma separated" wide>
        <input
          value={tool.required.join(', ')}
          onChange={(e) =>
            onChange({
              ...tool,
              required: e.target.value.split(',').map((s) => s.trim()).filter(Boolean),
            })
          }
        />
      </Field>
    </div>
  )
}
